insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 5, 'Pois o Senhor DEUS dos exércitos é o que toca a terra, e ela se derrete, e choram todos os que nela moram; ela toda subirá como um rio, e se afundará como o rio do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 6, 'Ele edificou suas câmaras no céu, e fundou seu alicerce sobre a terra; ele chama as águas do mar e as derrama sobre a terra. EU-SOU é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 7, 'Vós, filhos de Israel, por acaso não sois para mim como os filhos de Etíopes? Diz o SENHOR. Por acaso eu não fiz subir a Israel desde a terra do Egito, assim como os filisteus desde Caftor, e os sírios desde Quir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 8, 'Eis que os olhos do Senhor DEUS estão contra este reino pecador, e eu o exterminarei da face da terra; mas não exterminarei por completo a casa de Jacó, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 9, 'Porque eis que dou ordem para que a casa de Israel seja cirandada entre todas as nações, assim como [o grão] é cirandado na peneira, e nenhum grão cairá na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 10, 'Morrerão à espada todos os pecadores de meu povo, que dizem: O mal não chegará a nós, nem nos encontrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 11, 'Naquele dia voltarei a levantar a caída tenda de Davi; fecharei seus brechas, repararei suas ruínas, e a reconstruirei como nos dias antigos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 12, 'Para que tomem posse do restante de Edom, e todas as nações que se chamam pelo meu nome, diz o SENHOR, que faz isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 13, 'Eis que vêm dias, diz o SENHOR, em que o que ara alcançará ao que colhe, e o que pisa as uvas ao que leva a semente; e os montes destilarão suco de uva, e todos os morros se derreterão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 14, 'E restaurarei meu povo Isarael de seu infortúnio; então reconstruirão as cidades assoladas, e nelas habitarão; e plantarão vinhas, e beberão o vinho delas; e farão jardins, e comerão o fruto deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 15, 'Pois eu os plantarei em sua terra, e nunca mais serão arrancados de sua terra, que eu lhes dei, diz o SENHOR, teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 1, 'Visão de Obadias. Assim diz o Senhor DEUS quanto a Edom: Temos ouvido notícias do SENHOR, e mensageiro foi enviado entre as nações; levantai-vos, e nos levantaremos em batalha contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 2, 'Eis que eu te faço pequeno entre as nações; tu és muito desprezado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 3, 'A arrogância de teu coração te enganou, tu que habitas nas fendas das rochas, em teu alta morada; que dizes em teu coração: Quem me derrubará ao chão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 4, 'Se te elevares como a águia, e se puseres teu ninho entre as estrelas, dali eu te derrubarei,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 5, 'Se ladrões viessem a ti, ou assaltantes de noite, não furtariam [apenas] o que lhes bastasse? Se vindimadores viessem a ti, por acaso eles não deixariam algumas sobras? [Porém tu] , como estás arrasado!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 6, 'Como Esaú foi saqueado! Como seus tesouros foram tomados!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 7, 'Todos os teus aliados te moveram até as fronteiras; os que têm acordo de paz contigo te enganaram, prevaleceram contra ti; [os que comem] do teu pão porão armadilha para ti, (nele não há entendimento).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 8, 'Não será naquele dia,diz o SENHOR, que farei perecer os sábios de Edom, e o entendimento da montanha de Esaú?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 9, 'E teus guerreiros, ó Temã, ficarão atemorizados; para que cada um da montanha de Esaú seja exterminado pela matança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 10, 'Por causa da violência feita a teu irmão Jacó, a vergonha te cobrirá; e serás exterminado para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 11, 'No dia em que estavas diante [dele] , no dia em que estrangeiros levavam cativo seu exército, e estranhos entravam por suas portas e repartiam a posse de Jerusalém, tu também eras como um deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 12, 'Pois tu não devias olhar com prazer para o dia de teu irmão, o dia em que ele foi exilado; não devias te alegrar dos filhos de Judá no dia da ruína deles, nem falar com arrogância no dia da angústia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 13, 'Nem devias ter entrado pela porta de meu povo no dia de sua calamidade; não devias ter olhado seu mal no dia de sua calamidade, nem ter roubado seus bens no dia de sua calamidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 14, 'Nem devias ter ficado parado nas encruzilhadas, para exterminar os que dela escapassem; nem devias ter entregue os sobreviventes no dia da angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 15, 'Porque perto está o dia do SENHOR sobre todas as nações; como tu fizeste, assim se fará a ti; o pagamento devido voltará sobre tua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 16, 'Pois tal como vós bebestes no meu santo monte, assim também todas as nações beberão continuamente; beberão, e engolirão, e serão como se nunca tivessem existido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 17, 'Mas no monte de Sião haverá livramento, e ele voltará a ser santo; e a casa de Jacó tomará posse de suas propriedades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 18, 'E a casa de Jacó será fogo, a casa de José será chama, e os da casa de Esaú serão palha; e se incendiarão contra eles, e os consumirão, de modo que não haverá sobrevivente na casa de Esaú, porque o SENHOR falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 19, 'E os do Negueve possuirão a montanha de Esaú, e os da planície [tomarão posse da terra dos] filisteus; possuirão também os campos de Efraim, e os campos de Samaria; e Benjamim [tomará posse de] Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 20, 'E os cativos deste exército dos filhos de Israel [possuirão] o que era dos cananeus até Sarepta; e os cativos de Jerusalém, que estão em Sefarade, possuirão as cidades do Negueve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 31, 'Obadias', 'Ob', 1, 21, 'E salvadores se levantarão no monte de Sião, para julgarem ao monte de Esaú; e o reino pertencerá ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 1, 'E veio a palavra do SENHOR a Jonas, filho de Amitai, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 2, 'Levanta-te, vai à grande cidade de Nínive, e prega contra ela; porque sua maldade subiu diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 3, 'Porém Jonas se levantou para fugir da presença do SENHOR a Társis, e desceu a Jope; e achou um navio que partia para Társis. Então pagou sua passagem e entrou nele, para ir com eles a Társis [a fim de se distanciar] do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 4, 'Mas o SENHOR fez levantar um grande vento no mar; e fez-se uma tempestade tão grande no mar, que o navio estava a ponto de se quebrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 5, 'Então os marinheiros tiveram medo, e cada um clamava a seu deus; e lançaram no mar os objetos que havia no navio, para com eles diminuir o peso. Jonas, porém, havia descido ao interior do navio, e se pôs a dormir profundamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 6, 'E o capitão do navio se aproximou dele, e lhe disse: Que há contigo, dorminhoco? Levanta-te, e clama a teu deus; talvez ele se lembre de nós, para que não pereçamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 7, 'E disseram cada um a seu companheiro: Vinde, e lancemos sortes, para sabermos por causa de quem este mal [veio] sobre nós. Então lançaram sortes, e a sorte caiu sobre Jonas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 8, 'Então eles lhe disseram: Conta-nos, por favor, por que nos este mal nos [veio] . Qual é a tua profissão, e de onde vens? Qual é a tua terra, e de que povo és?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 9, 'E ele lhes respondeu: Sou hebreu, e temo ao SENHOR, o Deus dos céu, que fez o mar e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 10, 'Então aqueles homens tiveram um grande medo, e lhe disseram: Por que fizeste isto? Pois aqueles homens sabiam que ele estava fugindo do SENHOR, porque ele já havia lhes dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 11, 'Então lhe disseram: O que faremos contigo, para que o mar se nos aquiete?Porque o mar cada vez mais se embravecia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 12, 'E ele lhes respondeu: Tomai-me, e lançai-me ao mar, e o mar se vos aquietará; porque eu sei que foi por minha causa que esta grande tempestade [veio] sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 13, 'Mas os homens se esforçavam para remar, tentando voltar à terra firme; porém não conseguiam, porque o mar cada vez mais se embravecia sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 14, 'Então clamaram ao SENHOR, e disseram: Ó SENHOR, nós te pedimos para não perecermos por causa da alma deste homem, nem ponhas sangue inocente sobre nós; porque, tu, SENHOR, fizeste como te agradou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 15, 'Então tomaram a Jonas, e o lançaram ao mar; e o mar se aquietou de seu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 16, 'Por isso aqueles homens temeram ao SENHOR [com] grande temor; e ofereceram sacrifício ao SENHOR, e prometeram votos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 1, 17, 'Mas o SENHOR havia preparado um grande peixe para que tragasse a Jonas; e Jonas esteve três dias e três noites no ventre do peixe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 1, 'E Jonas orou ao SENHOR seu Deus, desde as entranhas do peixe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 2, 'E disse: Clamei da minha angústia ao SENHOR, e ele me respondeu; do ventre do Xeol gritei, [e] tu ouviste minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 3, 'Pois tu me lançaste no profundo, no meio dos mares, e a correnteza me cercou; todas as tuas ondas e tuas vagas passaram sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 4, 'E eu disse: Lançado estou de diante de teus olhos; porém voltarei a ver o teu santo templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 5, 'As águas me cercaram até a alma, o abismo me rodeou; as algas se enrolaram à minha cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 6, 'Desci aos fundamentos dos montes; a terra trancou suas fechaduras a mim para sempre; porém tu tiraste minha vida da destruição, ó SENHOR meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 7, 'Quando minha alma desfalecia em mim, eu me lembrei do SENHOR; e minha oração chegou a ti em teu santo templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 8, 'Os que dão atenção a coisas inúteis e ilusórias abandonam sua própria misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 9, 'Mas eu porém sacrificarei a ti com voz de gratidão; pagarei o que prometi. A salvação [vem] do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 2, 10, 'E o SENHOR falou ao peixe, e este vomitou a Jonas em terra firme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 1, 'E a palavra do SENHOR veio pela segunda vez a Jonas, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 2, 'Levanta-te, e vai à grande cidade de Nínive, e prega contra ela a pregação que eu te falo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 3, 'Então Jonas se levantou, e foi a Nínive, conforme a palavra do SENHOR. E Nínive era cidade extremamente grande, de três dias de caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 4, 'E Jonas começou a entrar pela cidade, caminho de um dia, e pregava dizendo: Daqui a quarenta dias Nínive será destruída.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 5, 'E os homens de Nínive creram em Deus; e convocaram um jejum, e se vestiram de sacos, desde o maior até o menor deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 6, 'Pois quando esta palavra chegou ao rei de Nínive, ele se levantou de seu trono, e lançou de si sua roupa, e cobriu-se de saco, e se sentou em cinzas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 7, 'E convocou e anunciou em Nínive, por mandado do rei e de seus maiorais, dizendo: Nem pessoas nem animais, nem bois nem ovelhas, provem coisa alguma, nem se lhes dê alimento, nem bebam água;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 8, 'E que as pessoas e os animais se cubram de saco, e clamem fortemente a Deus; e convertam- se cada um de seu mau caminho, e da violência que está em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 9, 'Quem sabe Deus mude de ideia e se arrependa, e se afaste do ardor de sua ira, para não perecermos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 3, 10, 'E Deus viu a atitude deles, que se converteram de seu mau caminho; então Deus se arrependeu do mal que tinha dito que lhes faria, e não o fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 1, 'Mas Jonas se desgostou muito, e se encheu de ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 2, 'E orou ao SENHOR, e disse: Ah, SENHOR, não foi isto o que eu dizia enquanto ainda estava em minha terra? Por isso me preveni fugindo a Társis; porque sabia eu que tu és Deus gracioso e misericordioso, que demoras a te irar, tens grande misericórdia, e te arrependes do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 3, 'Agora pois, ó SENHOR, peço-te que me mates, porque é melhor para mim morrer do que viver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 4, 'E o SENHOR lhe disse: É correta essa tua ira?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 5, 'E Jonas saiu da cidade, e se sentou ao oriente da cidade, e fez para si ali uma barraca, e se sentou debaixo dela à sombra, até ver o que seria da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 6, 'E o SENHOR Deus preparou uma planta, e a fez crescer sobre Jonas para que fizesse sombra sobre sua cabeça, e lhe aliviasse de seu mal-estar; e Jonas se alegrou grandemente por causa da planta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 7, 'Mas Deus preparou uma lagarta no dia seguinte ao amanhecer, a qual feriu a planta, e ela se secou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 8, 'E aconteceu que, ao levantar do sol, Deus preparou um quente vento oriental; e o sol feriu a Jonas na cabeça, de modo que ele se desmaiava, e desejava a morte, dizendo: Melhor é para mim morrer do que viver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 9, 'Então Deus disse a Jonas: É correta a tua ira pela planta?E ele respondeu: É correto eu me irar até a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 10, 'E o SENHOR disse: Tu tiveste pena da planta, na qual não trabalhaste, nem tu a fizeste crescer, que em uma noite nasceu, e em outra noite pereceu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 32, 'Jonas', 'Jn', 4, 11, 'E não teria eu pena de Nínive, aquela grande cidade onde há mais de cem e vinte mil pessoas que não sabem a diferença entre sua mão direita e a esquerda, e muitos animais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 1, 'Palavra do SENHOR que veio a Miqueias, o morastita, nos dias de Jotão, Acaz, [e] Ezequias, reis de Judá; que ele viu sobre Samaria e Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 2, 'Ouvi vós todos os povos; presta atenção tu, ó terra, e tudo o que nela há; pois o Senhor DEUS será testemunha contra vós, o Senhor desde seu santo templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 3, 'Porque eis que SENHOR está saindo de seu lugar, e descerá, e pisará os lugares altos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 4, 'E os montes debaixo dele se derreterão, e os vales se fenderão como a cera diante do fogo, como as águas se derramam por um precipício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 5, 'Tudo isto é por causa da transgressão de Jacó e dos pecados da casa de Israel. Qual é a transgressão de Jacó? Não é Samaria? E quais são os altos de Judá? Não é Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 6, 'Por isso tornarei a Samaria em amontoado de pedras no campo, em plantação de vinhas; e derrubarei suas pedras no vale, e descobrirei seus fundamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 7, 'E todas suas imagens de escultura serão esmigalhadas, e todos seus salários de prostituta serão queimados com fogo, e destruirei todos os seus ídolos; porque do salário de prostituta os ajuntou, e para salário de prostituta voltarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 8, 'Portanto lamentarei e uivarei, e andarei descalço e nu; farei uivos como de chacais, e lamentos como de filhotes de avestruzes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 9, 'Porque suas feridas são incuráveis, que já chegaram até Judá; [isto] já chegou até a porta do meu povo, até Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 10, 'Não anunciai [isto] em Gate, nem choreis tanto; revolve-te no pó em Bete-Le-Afra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 11, 'Passa-te com vergonha descoberta, ó moradora de Safir; a moradora de Zaanã não sai; pranto há em Bete-Ezel; seu apoio foi tomado de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 12, 'Porque a moradora de Marote anseiam à espera do bem; pois um mal desceu do SENHOR até a porta de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 13, 'Liga os cavalos à carruagem, ó moradora de Laquis (ela é o princípio do pecado à filha de Sião), porque em ti foram achadas as transgressões de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 14, 'Portanto, tu darás presentes de despedida a Moresete-Gate; as casas de Aczibe serão enganosas aos reis de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 15, 'Ainda trarei a ti um conquistador, ó moradora de Maressa; a glória de Israel virá até Adulão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 1, 16, 'Faz em ti calva, e rapa-te por causa dos filhos a quem gostavas; aumenta tua calva como a águia; porque foram levados de ti em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 1, 'Ai dos que planejam injustiça, e dos que tramam o mal em suas camas! Quando vem a manhã o efetuam, porque têm o poder em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 2, 'E cobiçam campos, e os roubam; cobiçam casas, e as tomam; oprimem ao homem e a sua casa, ao homem e a sua propriedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 3, 'Portanto, assim diz o SENHOR: Eis que eu planejo um mal contra esta família, da qual não conseguireis livrar vossos pescoços, nem andareis erguidos; porque o tempo será mau.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 4, 'Naquele tempo surgirá um provérbio sobre vós, e se lamentará um pranto de lamentação, dizendo: Fomos arruinados por completo; trocada foi a porção de meu povo. Como fomos saqueados! Nossos campos foram repartidos, passados a outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 5, 'Portanto a ninguém terás que delimite a propriedade de terra por meio de sortes na congregação do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 6, 'Não profetizeis! Falam eles. Não lhes profetizarão, [mas] a vergonha não se desviará deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 7, 'Por acaso se dirá, ó casa de Jacó: O espírito do SENHOR perdeu a paciência? São estas as suas obras? Por acaso minhas palavras não fazem bem ao que age corretamente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 8, 'Mas recentemente meu povo se levantou como inimigo; tomastes da roupa a capa daqueles que passavam confiantes, voltando da batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 9, 'Vós expulsais as mulheres de meu povo de suas queridas casas; de suas crianças tirastes minha glória para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 10, 'Levantai-vos, e ide embora, porque esta [terra] não serve mais para descanso; pois está contaminada, ela se destruirá, com grande destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 11, 'Se houver alguém que siga o vento, e fale mentiras e falsidade, dizendo: Eu te profetizarei vinho e de bebida alcoólica, este tal será o profeta deste povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 12, 'Certamente eu te ajuntarei por completo, ó Jacó; reunirei o restante de Israel; eu o porei junto, como ovelhas de Bosra, como rebanho no meio de seu curral farão estrondo de [multidão de] pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 2, 13, 'Aquele que rompe [obstáculos] subirá adiante deles; eles romperão, e passarão pela porta, e sairão por ela; e seu rei irá adiante deles, e o SENHOR estará em sua dianteira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 1, 'E eu disse: Ouvi agora, vós líderes de Jacó, e governantes da casa de Israel; por acaso não é vossa responsabilidade saber o que é justo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 2, 'Vós odiais o bem e amais o mal; vós roubais a pele dos outros, e a carne de seus ossos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 3, 'Vós sois os que comeis a carne de meu povo, e lhes tirais sua pele, e lhes quebrais seus ossos; e os despedaçais como para a panela, como carne dentro do caldeirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 4, 'Então clamareis ao SENHOR, mas ele não vos responderá; ao invés disso esconderá sua face diante de vós naquele tempo, pois praticastes maus atos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 5, 'Assim diz o SENHOR contra os profetas que fazem o meu povo errar, que quando recebem comida proclamam paz, mas declaram guerra contra quem não lhes dá de comer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 6, 'Portanto se vos fará noite por causa da profecia, e trevas por causa da adivinhação; e o sol se porá sobre estes profetas, e o dia se escurecerá sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 7, 'E os videntes se envergonharão, e os adivinhos serão humilhados; todos cobrirão o lábio, porque não haverá resposta de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 8, 'Porém eu estou cheio do poder do Espírito do SENHOR, e de juízo, e de força, para anunciar a Jacó sua transgressão, e a Israel seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 9, 'Ouvi agora isto, vós líderes da casa de Jacó, e governantes da casa de Israel, que abominais a justiça, e perverteis tudo o que é justo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 10, 'Vós edificais a Sião com sangue, e a Jerusalém com injustiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 11, 'Seus líderes julgam por suborno, seus sacerdotes ensinam por salário, e seus profetas adivinham por dinheiro; e se apoiam no SENHOR dizendo: Por acaso o SENHOR não está entre nós? Nenhum mal virá sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 3, 12, 'Portanto por causa de vós Sião será arada como campo, e Jerusalém se tornará um amontoado de pedras, e o monte do templo como os lugares altos de um bosque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 1, 'Mas acontecerá nos últimos dias que o monte da casa do SENHOR será firmado no cume de montes, e será mais elevado que os morros; e os povos correrão a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 2, 'E muitas nações virão e dirão: Vinde, e subamos ao monte do SENHOR, à casa do Deus de Jacó; e ele nos ensinará seus caminhos, e nós andaremos em suas veredas; porque a lei virá de Sião, e a palavra do SENHOR de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 3, 'E ele julgará entre muitos povos, e corrigirá poderosas nações até muito longe; e adaptarão suas espadas para enxadas, e suas lanças para foices; nação não erguerá espada contra nação, nem mais aprenderão a [fazer] guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 4, 'E cada um se sentará debaixo de sua videira e debaixo de sua figueira, e não haverá quem lhes cause medo; porque a boca do SENHOR dos exércitos assim falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 5, 'Pois todos os povos andam cada um no nome de seus deuses; nós, porém, andaremos no nome do SENHOR nosso Deus para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 6, 'Naquele dia,diz o SENHOR, reunirei a que mancava, e ajuntarei a que havia sido expulsa, e a que eu tinha maltratado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 7, 'E farei da que mancava um [povo] restante, da que havia sido expulsa uma nação poderosa; e o SENHOR reinará sobre eles no monte de Sião desde agora para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 8, 'E tu, ó torre de vigilância do rebanho, tu fortaleza da filha de Sião, virá a ti o primeiro domínio; o reino chegará à filha de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 9, 'Agora por que gritas tanto? Não há rei em ti? Pereceu teu conselheiro, para que tenhas sido tomada por dores como as de parto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 10, 'Sofre dores e contorce-te, ó filha de Sião, como mulher em trabalho de parto; porque agora sairás da cidade, e morarás no campo, e virás até a Babilônia; [porém] ali tu serás livrada, ali o SENHOR te redimirá da mão de teus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 11, 'Mas agora muitas nações se reuniram contra ti, e dizem: Seja profanada, e nossos olhos vejam a desgraça de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 12, 'Mas elas não sabem os pensamentos do SENHOR, nem entendem seu conselho; de que ele as ajuntou como a feixes para a eira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 4, 13, 'Levanta-te e trilha, ó filha de Sião, porque tornarei teu chifre de ferro, e tuas unhas de bronze, e esmiuçarás muitos povos; e consagrarás ao SENHOR seus ganhos, e seus bens ao Senhor de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 1, 'Agora ajunta-te em tropas, ó filha de tropas; fazem cerco ao nosso redor; ferirão ao juiz de Israel com vara no rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 2, 'Porém tu, Belém Efrata, [ainda que] sejas pequena entre as famílias de Judá, de ti me sairá o que será governador em Israel; e suas saídas são desde o princípio, desde os dias antigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 3, 'Por isso ele os entregará até o tempo em que a que estiver de parto der à luz; então o resto de seus irmãos voltarão a estar com os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 4, 'E eles se levantará, e governará com a força do SENHOR, com a grandeza do nome do SENHOR seu Deus; e eles habitarão [seguros] ,porque agora ele será engrandecido até os confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 5, 'E este será nossa paz; quando a Assíria vier a nossa terra, e quando pisar nossos palácios, então levantaremos contra ela sete pastores, e oito príncipes dentre os homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 6, 'E dominarão a terra da Assíria pela espada, e a terra de Ninrode em suas entradas; assim ele [nos] livrará do assírios, quando vierem contra nossa terra e invadirem nossas fronteiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 7, 'E o restante de Jacó estará no meio de muitos povos, como o orvalho do SENHOR, como gotas sobre a erva, que não esperam ao homem, nem aguardam os filhos de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 8, 'E o restante de Jacó estará entre as nações, no meio de muitos povos, como o leão entre os animais do bosque, como o leão jovem entre os rebanhos de ovelhas, o qual quando passa, atropela e despedaça, de modo que ninguém há que possa livrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 9, 'Tua mão se erguerá sobre teus adversários, e todos os teus inimigos serão exterminados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 10, 'E será naquele dia,diz o SENHOR, que destruirei teus cavalos do meio de ti, e acabarei com tuas carruagens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 11, 'Também destruirei as cidades da tua terra, e derrubarei todas as tuas fortalezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 12, 'Também destruirei as feitiçarias de tua mão, e não terás mais adivinhadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 13, 'Também destruirei as tuas imagens de escultura e tuas colunas de idolatria do meio de ti, e nunca mais te encurvarás diante da obra de tuas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 14, 'Também arrancarei teus bosques do meio de ti, e arruinarei tuas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 5, 15, 'E com ira e com furor farei vingança das nações que não [me] deram ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 1, 'Ouvi agora o que o SENHOR diz: Levanta-te, briga com os montes, e ouçam os morros a tua voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 2, 'Ouvi vós, montes, e vós, fortes fundamentos da terra, a briga do SENHOR; porque o SENHOR tem uma briga judicial com seu povo, e disputará judicialmente com Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 3, 'Ó povo meu, o que eu tenho feito a ti? Em que eu te incomodei? Responde-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 4, 'Pois eu te fiz subir da terra do Egito, e da casa de escravidão eu te livrei; e enviei diante de ti a Moisés, Arão, e Miriã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 5, 'Ó povo meu, lembra-te agora do Balaque, rei de Moabe, planejou, e do que Balaão, filho de Beor, lhe respondeu, [e do que aconteceu] desde Sitim até Gilgal, para que conheças as justiças do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 6, 'Com que me encontrarei com o SENHOR, [e] adorarei ao alto Deus? Virei diante ele com holocaustos, com bezerros de um ano?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 7, 'O SENHOR se agradará de milhares de carneiros, [ou] de dez mil ribeiros de azeite? Darei meu primogênito por minha transgressão, o fruto de meu ventre pelo pecado de minha alma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 8, 'Ele já declarou a ti, ó ser humano, o que é bom; e que mais o SENHOR pede de ti, a não ser fazer o que é justo, amar a bondade, e andar humildemente com teu Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 9, 'A voz do SENHOR clama à cidade (e sábio é temer o teu nome): Ouvi a vara, e a quem a estabeleceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 10, 'Não há ainda na casa do perverso riquezas da perversidade, e medida enganosamente menor, o que é abominável?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 11, 'Posso eu tolerar [quem tem] balanças falsas e bolsa de pesos enganosos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 12, 'Pois seus ricos estão cheios de violência, e seus moradores falaram mentiras, e suas línguas são enganosas em suas bocas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 13, 'Por isso eu também [te] enfraquecerei, ferindo-te e assolando-te por teus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 14, 'Tu comerás, mas não te saciarás; e fome haverá no meio de ti; tu pegarás, mas não levarás [contigo] ; e o que levares, eu [o] entregarei à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 15, 'Tu semearás, mas não colherás; pisarás azeitonas, mas não te ungirás com óleo; [pisarás] uvas, mas não beberás vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 6, 16, 'Pois são os mandamentos de Onri, e todas as obras da casa de Acabe, que são obedecidos; e vós praticais seus conselhos. Por isso eu te tornarei desolada, e teus moradores serão motivo de assovio. Assim levareis a humilhação de meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 1, 'Ai de mim! Porque sou como quando os frutos do verão são colhidos, como quando são tiradas as sobras das uvas da vindima, de modo que não resta cacho de uvas para comer; minha alma deseja frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 2, 'Já pereceu o misericordioso da terra, e não há quem seja justo entre os seres humanos; todos armam ciladas em busca de sangue; cada um arma rede de caça a seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 3, 'Suas mãos são habilidosas em fazer o mal; o príncipe dá ordens e o juiz julga por propina; e o grande fala o mau desejo de sua alma, e colaboram com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 4, 'O melhor dentre eles é como o espinho; o mais justo é como o espinheiro. O dia de teus vigilantes, teu castigo, vem; agora será sua confusão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 5, 'Não creiais em amigo, nem confieis em príncipe; guardas as portas de tua boca daquela que dorme ao teu lado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 6, 'Porque o filho despreza o pai, a filha se levanta contra sua mãe, a nora contra sua sogra; e os inimigos do homem são os de sua própria casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 7, 'Eu, porém, observarei ao SENHOR, esperarei ao Deus de minha salvação; meu Deus me ouvirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 8, 'Ó minha inimiga, não te alegres de mim; pois ainda que tenha caído, eu me levantarei; ainda que eu esteja assentado em trevas, o SENHOR será minha luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 9, 'Suportarei a ira do SENHOR, porque pequei contra ele; [suportarei] até que ele julgue minha causa e execute meu direito; ele me trará para a luz; eu verei sua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 10, 'E minha inimiga verá [isso] ,e a vergonha a cobrirá; ela que me dizia: Onde está o SENHOR teu Deus? Meus olhos a verão; agora ela será pisada como a lama das ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 11, 'No dia em que teus muros forem reconstruídos, naquele dia as fronteiras se ampliarão para longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 12, 'Naquele dia virão a ti da Assíria até as cidades fortes, das cidades fortes até o rio, e de mar a mar, e de monte a monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 13, 'Porém esta terra será desolada por causa de seus moradores, por causa do fruto de suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 14, 'Apascenta teu povo com teu cajado, o rebanho de tua herança, que mora só no bosque, no meio do campo fértil; que se alimentem em Basã e Gileade, como nos dias antigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 15, 'Eu lhes farei ver maravilhas, como nos dias em que saíste da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 16, 'As nações verão, e se envergonharão de todo o seu poder; porão a mão sobre a boca, ensurdecerão seus ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 17, 'Lamberão o pó como a serpente; como os répteis da terra sairão tremendo de seus esconderijos; eles ficarão apavorados com o SENHOR nosso Deus, e temerão a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 18, 'Quem é Deus como tu, que perdoa a maldade, e ignora a transgressão do restante de sua herança? Ele não retém para sempre sua ira, porque ele tem prazer na bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 19, 'Ele voltará a ter misericórdia de nós; ele esmagará nossas maldades. Tu lançarás os pecados deles nas profundezas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 33, 'Miquéias', 'Mq', 7, 20, 'Tu concederás a Jacó a fidelidade, e a Abraão a bondade, que juraste a nossos pais desde os dias antigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 1, 'Revelação sobre Nínive. Livro da visão de Naum o elcosita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 2, 'O SENHOR é Deus zeloso e vingador; o SENHOR é vingador e furioso; o SENHOR se vinga de seus adversários, e que guarda [ira] contra seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 3, 'O SENHOR é tardio para se irar, porém grande em poder; e não terá [ao culpado] por inocente. O SENHOR caminha entre a tempestade e o turbilhão, e as nuvens são o pó de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 4, 'Ele repreende o mar, e o faz secar; e deixa secos todos os rios. Basã e o Carmelo se definham, e a flor do Líbano murcha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 5, 'Os montes tremem diante dele, e os morros se derretem; e a terra se abala em sua presença, e o mundo, e todos os que nele habitam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 6, 'Quem pode subsistir diante de seu furor? E quem pode persistir diante do ardor de sua ira? Seu furor se derrama como fogo, e as rochas se partem diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 7, 'O SENHOR é bom, é fortaleza no dia da angústia; ele conhece os que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 8, 'Mas com inundação impetuosa ele acabará com Nínive, e perseguirá seus inimigos até às trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 9, 'O que vós tramais contra o SENHOR, ele mesmo destruirá; a angústia não se levantará duas vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 10, 'Mesmo estando entretecidos como espinhos, e embriagados como beberrões, eles serão consumidos como a palha seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 11, 'De ti saiu um que trama o mal contra o SENHOR, um conselheiro maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 12, 'Assim diz o SENHOR: Ainda que sejam prósperos, e muitos em número, mesmo assim eles serão exterminados, e passarão. Eu te afligi, [Judá] , porém não te afligirei mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 13, 'Mas agora quebrarei seu jugo de sobre ti, e romperei tuas amarras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 14, 'Porém contra ti, [assírio] , o SENHOR mandou que nunca mais seja gerado alguém de teu nome; da casa de teu deus arrancarei as imagens de escultura e de fundição. Farei para ti um sepulcro, porque tu és desprezível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 1, 15, 'Eis que sobre os montes estão os pés daquele que anuncia boas novas, do que faz ouvir a paz. Celebra tuas festas, Judá; cumpre os teus votos, porque nunca mais o maligno passará por ti; ele foi exterminado por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 1, 'O despedaçador está subindo contra ti; guarda a fortaleza, olha para o caminho, prepara os lombos, junta o poder de tuas forças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 2, 'Porque o SENHOR restituirá a glória de Jacó, como a glória de Israel, ainda que saqueadores tenham os saqueado, e destruído os seus ramos de videira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 3, 'Os escudos de seus guerreiros são vermelhos, os homens valentes andam vestidos de escarlate; as carruagens brilham no dia em que são preparadas, as lanças se sacodem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 4, 'As carruagens se movem furiosamente pelas ruas, percorrem as vias; sua aparência é como tochas, correm como relâmpagos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 5, 'Seus nobres são convocados, porém tropeçam enquanto marcham; eles se apressam ao seu muro, e a proteção é preparada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 6, 'As comportas dos rios são abertas, e o palácio é arruinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 7, 'Está decretado: ela será levada cativa, e suas criadas a acompanharão com voz de pombas, batendo seus peitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 8, 'Nínive é como um antigo tanque, cujas águas estão fugindo. [Dizem] : Parai, parai; porém ninguém sequer olha para trás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 9, 'Saqueai prata, saqueai ouro; não há fim das riquezas e do luxo, de todo tipo de objetos valiosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 10, 'Ela está esvaziada, devastada e arruinada; os corações desmaiam, os joelhos tremem, os lombos doem, e os rostos deles todos ficam abatidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 11, 'Onde está a morada dos leões, e o lugar onde os leões jovens se alimentavam, onde o leão, a leoa, e os filhotes de leão passeavam, e não havia quem os espantasse?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 12, 'O leão caçava o suficiente para seus filhotes, e estrangulava para as suas leoas, e enchia suas cavernas de presa, e suas moradas de coisas capturadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 2, 13, 'Eis que eu sou contra ti,diz o SENHOR dos exércitos. Queimarei as tuas carruagens em fumaça, e espada consumirá teus jovens leões; exterminarei a tua presa da terra, e nunca mais a voz de teus mensageiros será ouvida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 1, 'Ai da cidade sanguinária, toda cheia de mentiras e de saques; o roubo não cessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 2, '[Ali há] o som de açoite, e o estrondo do mover de rodas; os cavalos atropelam, e as carruagens vão se sacudindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 3, 'O cavaleiro ataca, a espada brilha, e a lança resplandece; e [ali haverá] muitos mortos, e multidão de cadáveres; haverá corpos sem fim, e tropeçarão nos corpos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 4, 'Por causa da multidão das prostituições da prostituta muito charmosa, mestra de feitiçarias, que vende os povos com suas prostituições, e as famílias com suas feitiçarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 5, 'Eis que estou contra ti,diz o SENHOR dos exércitos, e descobrirei tuas saias sobre tua face, e mostrarei tua nudez às nações, tua vergonha aos reinos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 6, 'E lançarei sobre ti coisas abomináveis, e te envergonharei, e te tornarei em ridículo público.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 7, 'E será que todos os que te virem fugirão de ti, e dirão: Nínive está destruída; quem terá compaixão dela? Onde buscarei para ti consoladores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 8, 'És tu melhor que Nô-Amom, que estava situada entre os rios, cercada de águas, cuja fortificação era o mar, e o rio como muralha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 9, 'Cuxe e Egito era sua fortaleza sem limites; Pute e Líbia estavam para tua ajuda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 10, 'Porém ela foi levada em cativeiro; também suas crianças foram despedaçadas nas esquinas de todas as ruas; e sobre seus nobres lançaram sortes, e todos seus maiorais foram aprisionados com grilhões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 11, 'Tu também estarás bêbada, [e] te esconderás; tu também buscarás fortaleza por causa do inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 12, 'Todas as tuas fortalezas são [como] figueiras com os primeiros figos, que ao serem sacudidas, caem na boca de quem quer comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 13, 'Eis que teu exército será como mulheres no meio de ti; as portas de tua terra se abrirão a teus inimigos; fogo consumirá teus ferrolhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 14, 'Reserva para ti água para o cerco, fortifica as tuas fortalezas; entra na lama, pisa o barro, conserta o forno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 15, 'Ali o fogo te consumirá, a espada te cortará, te consumirá como o inseto devorador. Multiplica-te como o inseto devorador; multiplica-te como o gafanhoto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 16, 'Multiplicaste teus mercadores mais que as estrelas do céu; o inseto devorador estende as asas, e sai voando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 17, 'Teus oficiais são como gafanhotos, e teus capitães como enxames de gafanhotos que pousam em nas paredes nos dias de frio; quando o sol se levanta eles voam, de modo que não se pode saber seu lugar onde estiveram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 18, 'Teus pastores cochilam, ó rei da Assíria, teus nobres descansam; teu povo se espalhou pelos montes, e ninguém o ajuntará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 34, 'Naum', 'Na', 3, 19, 'Não há cura para tua ferida; tua chaga é fatal; todos os que ouviram tua fama baterão palmas por causa de ti, pois sobre quem tua maldade não passou continuamente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 1, 'Revelação que o profeta Habacuque viu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 2, 'Até quando, SENHOR, eu clamarei, e tu não ouvirás? [Até quando] gritarei a ti: Violência!, e tu não salvarás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 3, 'Por que me fazes ver a injustiça, e vês a opressão? Pois assolação e violência estão em frente de mim, há brigas, e disputas se levantam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 4, 'Por isso que a lei é enfraquecida, e o juízo nunca se cumpre: porque o perverso cerca o justo, por o juízo é distorcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 5, 'Vede entre as nações, e prestai atenção, e espantai-vos, espantai-vos; porque uma obra será feita em vossos dias, que quando for contada, não acreditareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 6, 'Porque eis que eu levanto os caldeus, uma nação amarga e veloz, que caminha pelas larguras da terra para tomar posse de moradas que não são suas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 7, 'Ela é espantosa é e terrível; que impõe seu próprio julgamento e sua própria honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 8, 'E seus cavalos são mais rápidos que os leopardos, e mais ferozes que lobos de tarde; e seus cavaleiros avançam; seus cavaleiros virão de longe, e voarão como águias que se apressam para devorar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 9, 'Todos eles vêm para [fazer] violência; seus rostos estão orientados; e juntarão cativos como areia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 10, 'E escarnecerão dos reis, e zombarão dos príncipes; rirão de todas as fortalezas, porque amontoarão terra, e as tomarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 11, 'Logo mudarão, e passarão adiante como o vento; porém culpado será quem confiar na força de seu deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 12, 'Não és tu desde o princípio, ó SENHOR, meu Deus, meu Santo? Não morreremos. Ó SENHOR, tu os puseste para [executar] o julgamento; e tu, ó Rocha, os estabeleceste para castigar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 13, 'Teus olhos são puros demais para veres o mal, e não podes observar a opressão; ora, por que olharias aos enganadores, e calarias quando o perverso devora ao mais justo que ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 14, 'Tornarias as pessoas como como os peixes do mar, como répteis que não têm quem os governe?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 15, 'Ele tira a todos com anzol, em sua malha os ajunta, e os colhe em seu rede; por isso ele se alegra e tem prazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 16, 'Por isso ele faz sacrifícios à sua malha, e oferece incensos à sua rede; porque com elas enriqueceu sua porção, e engordou sua comida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 1, 17, 'Continuará ele, pois, a esvaziar a sua malha, e a matar as nações continuamente sem ter compaixão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 1, 'Sobre o meu posto de guarda estarei, e sobre a fortaleza ficarei e vigiarei, para ver o que ele me falará, e o que eu responderei à minha queixa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 2, 'Então o SENHOR me respondeu, e disse: Escreve a visão, e a põe claramente em tábuas, para que mesmo quem esteja correndo consiga ler.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 3, 'Pois a visão ainda é para um tempo determinado, mas ao fim ela dará testemunho, e não mentirá; se tardar, espera, porque virá; não se atrasará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 4, 'Eis que o soberbo não tem a alma correta em si; mas o justo viverá por sua fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 5, 'Pois também o vinho é enganador, [é como] um homem arrogante, que não fica quieto em casa; sua avidez se alarga como o Xeol, e se assemelha à morte, que não se farta; e ajunta para si todas as nações, e reúne para si todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 6, 'Por acaso todos estes não levantarão um insulto e provérbios de zombaria contra ele? E dirão: Ai daquele que acumula o que não era seu, e daquele de se enriquece por meio de extorsão! Até quando?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 7, 'Por acaso não se levantarão de repente seus credores, e se despertarão os que te fazem tremer? Tu serás despojado por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 8, 'Visto que tu despojaste muitas nações, todos os povos restantes te despojarão; por causa do sangue das pessoas, e da violência contra a terra, as cidades e todos os seus moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 9, 'Ai daquele que obtém [riquezas] para sua casa por meios malignos, para pôr no alto seu ninho, para tentar se livrar do poder da calamidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 10, 'Tramaste plano vergonhoso para tua casa, exterminaste muitos povos, e pecaste contra tua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 11, 'Porque a pedra clamará desde a parede, e a trave desde a estrutura de madeiras lhe responderá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 12, 'Ai daquele que edifica a cidade com sangues, e do que estabelece a vila com perversidade!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 13, 'Eis que isto não vem da parte do SENHOR dos exércitos, que os povos trabalham para o fogo, e as nações se cansam em vão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 14, 'Porque a terra se encherá de conhecimento da glória do SENHOR, como as águas cobrem o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 15, 'Ai daquele que dá bebidas a seu próximo, tu que embebedas com teu furor, para que possas vê-los nus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 16, 'Tu te encherás de vergonha no lugar de honra; bebe tu também, e descobre o prepúcio; o cálice da mão direita do SENHOR voltará sobre ti, e haverá vergonha sobre a tua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 17, 'Porque a violência cometida contra o Líbano te cobrirá, e a destruição dos animais selvagens o assombrará; por causa dos sangues das pessoas, e da violência contra a terra, as cidades, e todos os seus moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 18, 'Que proveito há na imagem de escultura, que seu formador a esculpiu? E na imagem de fundição, que ensina mentiras? Quem a formou nela confia, tendo feito ídolos mudos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 19, 'Ai daquele que diz ao pedaço de madeira: Desperta-te; e à pedra muda: Levanta-te! Poderá essa coisa ensinar? Eis que está coberta de ouro e prata, mas não há dentro dela espírito algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 2, 20, 'Porém o SENHOR está em seu santo templo; que toda a terra se cale diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 1, 'Oração do profeta Habacuque, conforme “Siguionote”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 2, 'Ó SENHOR, ouvido tenho tua fama; temi, Ó SENHOR, a tua obra; renova-a no meio dos anos; faze-a conhecida no meio dos anos; na ira lembra-te da misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 3, 'Deus veio de Temã, o Santo do monte de Parã (Selá). Sua glória cobriu os céus, e a terra se encheu de seu louvor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 4, 'E houve resplendor como o da luz; raios brilhantes saíam de sua mão; e ali sua força estava escondida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 5, 'A praga ia adiante dele, e a pestilência seguia seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 6, 'Ele parou, e sacudiu a terra; ele olhou, e abalou as nações; e os montes antigos foram despedaçados, os morros antigos caíram. Seus caminhos são eternos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 7, 'Vi as tendas de Cusã em aflição; as cortinas da terra de Midiã tremeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 8, 'Por acaso o SENHOR se irritou contra os rios? Foi tua ira contra os ribeiros? Foi tua ira contra o mar, quando cavalgaste sobre teus cavalos, e tuas carruagens de vitória?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 9, 'Teu arco foi descoberto, as flechas foram preparadas pela [tua] palavra (Selá). Fendeste a terra com rios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 10, 'Os montes te viram, e tiveram dores; a inundação das águas passou. O abismo deu sua voz, e levantou suas mãos ao alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 11, 'O sol e a lua pararam em suas moradas; à luz de tuas flechas passaram, com o resplendor de tua lança relampejante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 12, 'Com indignação marchaste pela terra, com ira trilhaste as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 13, 'Saíste para a salvar o teu povo, para salvar o teu ungido. Feriste o líder da casa do ímpio, descobrindo-o dos pés ao pescoço. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 14, 'Perfuraste com suas próprias lanças os líderes de suas tropas, que vieram impetuosamente para me dispersarem. A alegria deles era como a de devorarem os pobres às escondidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 15, 'Pisaste pelo mar com teus cavalos, pela turbulência de grandes águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 16, 'Quando eu ouvi, meu ventre se perturbou; por causa do ruído meus lábios tremeram; podridão veio em meus ossos, e em meu lugar me perturbei; descansarei até o dia da angústia, quando virá contra o povo que nos ataca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 17, 'Ainda que a figueira não floresça, nem haja fruto nas vides, e falte o produto da oliveira, os campos não produzam alimento, as ovelhas sejam arrebatadas, e não haja vacas nos currais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 18, 'Mesmo assim eu me alegrarei no SENHOR, terei prazer no Deus de minha salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 35, 'Habacuque', 'Hc', 3, 19, 'DEUS, o Senhor, é minha fortaleza; ele fará meus pés como os das corças, e me fará andar sobre meus lugares altos.(Para o regente, com instrumentos de cordas).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 1, 'Palavra do SENHOR que veio a Sofonias filho de Cuxi, filho de Gedalias, filho de Amarias, filho de Ezequias, nos dias de Josias filho de Amom, rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 2, 'Destruirei tudo de sobre a face da terra,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 3, 'Destruirei as pessoas e os animais; destruirei as aves do céu, e os peixes do mar, e as pedras de tropeço com os perversos; e exterminarei os seres humanos de sobre a face da terra,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 4, 'E estenderei minha mão contra Judá, e contra todos os moradores de Jerusalém; e exterminarei deste lugar o restante de Baal, [e] o nome dos idólatras com os sacerdotes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 5, 'E os que se encurvam sobre os terraços ao exército do céu; e aos que se encurvam jurando pelo SENHOR, mas também jurando por Milcom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 6, 'E aos que dão as costas ao SENHOR, aos que não buscam ao SENHOR, nem perguntam por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 7, 'Cala-te na presença do Senhor DEUS, porque o dia do SENHOR está perto; porque o SENHOR tem preparado um sacrifício, [e] santificou a seus convidados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 8, 'E será que, no dia do sacrifício do SENHOR, punirei os príncipes, os filhos do rei, e todos os que vestem roupas estrangeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 9, 'Também punirei naquele dia todos os que saltam sobre o umbral, os que enchem as casas de seus senhores de [produtos de] violência e de engano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 10, 'E naquele dia,diz o SENHOR, haverá voz de clamor desde a porta dos peixes, lamentação desde a segunda parte [da cidade] ,e grande quebrantamento desde os morros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 11, 'Lamentai, vós moradores do vale, porque todo o povo mercador está destruído; todos os que pesavam dinheiro são exterminados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 12, 'E será naquele tempo, que farei busca em Jerusalém com lâmpadas, e punirei os homens que estão acomodados como sedimentos de vinho, os quais dizem em seu coração: O SENHOR nem fará bem nem mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 13, 'Por isso a riqueza deles será despojada, e suas casas serão arruinadas; edificarão casas, mas não habitarão nelas; e plantarão vinhas, mas não beberão seu vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 14, 'Perto está o grande dia do SENHOR; perto está, e com muita pressa se aproxima; a voz do Dia do SENHOR; ali o guerreiro gritará amargamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 15, 'Aquele dia será dia de fúria; dia de angústia e de aflição, dia de devastação e de ruína; dia de trevas e de escuridão, dia de nuvens e de espessa obscuridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 16, 'Dia de trombeta e de alarme contra as cidades forte e contra as torres as altas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 17, 'E angustiarei as pessoas, que andarão como cegas, porque pecaram contra o SENHOR; e o sangue delas será derramado como pó, e sua carne será como esterco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 1, 18, 'Nem sua prata nem seu ouro poderá os livrar no dia do furor do SENHOR; pois toda esta terra será consumida pelo fogo de seu zelo; porque ele certamente fará destruição repentina com todos os moradores da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 1, 'Ajuntai-vos, ajuntai-vos, ó nação desagradável,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 2, 'Antes que o decreto se concretize, e o dia se passe como a palha; antes que o ardor da ira do SENHOR venha sobre vós, antes que o dia da ira do SENHOR venha sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 3, 'Buscai ao SENHOR todos vós mansos da terra, que praticam seu juízo; buscai justiça, buscai mansidão; talvez sejais preservados no dia da ira do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 4, 'Porque Gaza será desamparada, e Asquelom desolada; Asdode será expelida ao meio dia, e Ecrom será arrancada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 5, 'Ai dos que moram à margem do mar, da nação dos quereteus! A palavra do SENHOR é contra vós, ó Canaã, terra dos filisteus; e eu vos destruirei, até que não haja morador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 6, 'E a margem do mar se tornará pastagens, com abrigos de pastores, e currais de rebanhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 7, 'E aquela região será para o restante da casa de Judá, para que nela apascentem; ao anoitecer se deitarão nas casas de Asquelom, porque o SENHOR, seu Deus, os visitará, e os restaurará de seu infortúnio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 8, 'Eu ouvi os escárnios de Moabe, e os insultos dos filhos de Amom com que escarneceram a meu povo, e se engrandeceram contra suas fronteiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 9, 'Portanto vivo eu,diz o SENHOR dos exércitos, Deus de Israel, que Moabe será como Sodoma, e os filhos de Amom como Gomorra; campo de urtigas, e mina de sal, e desolação perpétua; o restante de meu povo os saqueará, e o restante de minha nação tomará posse daquilo que era deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 10, 'Isto terão por sua soberba, porque escarneceram e se engrandeceram contra o povo do SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 11, 'O SENHOR será terrível contra eles, porque ele consumirá a todos os deuses da terra; e cada um desde seu lugar o adorará, todas as regiões costeiras das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 12, 'Também vós cuxitas sereis mortos pela minha espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 13, 'E ele estenderá sua mão contra o norte, e destruirá a Assíria, e tornará Nínive em desolação e em secura como deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 14, 'E no meio dela os rebanhos de gado se deitarão, todas os animais das nações; também o corvo a coruja passarão a noite em seus pilares; sua voz se ouvirá nas janelas; assolação será nos umbrais, porque sua estrutura de cedro estará descoberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 2, 15, 'Esta é a cidade alegre que habita segura, que diz em seu coração: Nenhuma outra há como eu sou. Como ela se tornará em desolação, [em] repouso de animais! Qualquer um que passar perto dela assoviará [e] sacudirá sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 1, 'Ai da suja e contaminada, da cidade opressora!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 2, 'Ela não ouve a voz, nem aceita o castigo; não confia no SENHOR, não se achega a seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 3, 'Seus príncipes no meio dela são leões que rugem; seus juízes são lobos da noite que nada deixam para a manhã [seguinte] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 4, 'Seus profetas são levianos, homens enganadores; seus sacerdotes profanam o santuário, [e] violentam a lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 5, 'O SENHOR é justo em meio dela, não faz perversidade; de manhã ele tira seu juízo à luz, nunca falha; mas o injusto não conhece a vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 6, 'Exterminei as nações; suas muralhas estão arruinadas, suas ruas estão desertas, de maneira que ninguém passe por elas; suas cidades estão desoladas de maneira que ninguém restou, nenhum morador sequer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 7, 'Eu dizia: Certamente me temerás, aceitarás a correção; para que assim sua morada não seja destruída [por] tudo aquilo que eu havia determinado sobre ela. Porém eles se levantaram de manhã e corromperam todos os seus atos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 8, 'Portanto esperai em mim,diz o SENHOR, pelo dia em que me levantarei para o despojo; porque minha determinação é ajuntar as nações, reunir os reinos, para derramar sobre eles minha indignação, todo o ardor de minha ira; pois toda a terra será consumida pelo o fogo do meu zelo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 9, 'Então certamente darei lábio puro aos povos, para que todos invoquem o nome do SENHOR, para que lhe sirvam em unidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 10, 'Dalém dos rios de Cuxe, meus adoradores, a filha de meus dispersos, me trarão oferta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 11, 'Naquele dia não serás envergonhada por nenhum de teus atos com que transgrediste contra mim; porque então tirarei do meio de ti os que se alegram por tua soberba, e nunca mais te exaltarás por causa do meu monte santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 12, 'Mas farei restar no meio de ti um povo humilde e pobre; e eles confiarão no nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 13, 'O restante de Israel não cometerá perversidade, nem falarão mentiras, nem se achará em suas bocas língua enganosa; em vez disso eles serão apascentados e se deitarão, e não haverá quem os espante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 14, 'Canta alegremente, ó filha de Sião; grita de alegria, ó Israel; alegra-te e anima-te de todo coração, ó filha de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 15, 'O SENHOR afastou os julgamentos contra ti, exterminou teu inimigo; o SENHOR, Rei de Israel, está no meio de ti; nunca mais verás mal algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 16, 'Naquele dia se dirá a Jerusalém: Não temas, Sião, não se enfraqueçam tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 17, 'O SENHOR está no meio de ti, guerreiro que salva; ele terá prazer em ti com alegria; ele [te] aquietará em seu amor, se encherá de alegria por causa de ti com júbilo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 18, 'Ajuntarei aos que se entristecem [de saudade] das reuniões solenes; eles eram teus; para eles a humilhação dela era uma peso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 19, 'Eis que naquele tempo acabarei com todos os teus opressores; e salvarei a manca, e ajuntarei a expulsa; e os tornarei louvor e renome em toda terra em que foram envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 36, 'Sofonias', 'Sf', 3, 20, 'Naquele tempo eu vos trarei de volta, naquele tempo eu vos ajuntarei; pois vos tornarei renome e louvor entre todos os povos da terra, quando eu vos resutaurar de vosso infortúnio diante de vossos olhos, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 1, 'No segundo ano segundo do rei Dario, no sexto mês, no primeiro dia do mês, veio a palavra do SENHOR, por meio do profeta Ageu, a Zorobabel filho de Sealtiel, governador de Judá, e a Josué filho de Jeozadaque, sumo sacerdote, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 2, 'Assim fala o SENHOR dos exércitos: Este povo diz: O tempo não chegou, o tempo da casa do SENHOR ser reconstruída.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 3, 'Veio, pois, a palavra do SENHOR por meio do profeta Ageu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 4, 'Por acaso é para vós tempo de morar em vossas casas com telhado, e esta casa ficar deserta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 5, 'Pois assim diz o SENHOR dos exércitos: Considerai vossos caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 6, 'Semeais muito, mas colheis pouco; comeis, mas não vos fartais; bebeis, mas não vos satisfazeis; vós vos vestis, mas não vos aqueceis; e o assalariado recebe seu salário em bolsa furada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 7, 'Assim diz o SENHOR dos exércitos: Considerai vossos caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 8, 'Subi vós à montanha, trazei madeira, e reconstruí a casa; e dela me agradarei, e serei glorificado,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 9, 'Esperastes por muito, e alcançastes pouco; e quando o trouxestes para casa, eu soprei nisso. Por que isto?,diz o SENHOR dos exércitos. Porque minha casa está deserta, e cada um de vós corre para sua própria casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 10, 'Por isso que os céus detêm o orvalho de vós, e a terra detém seus frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 11, 'E chamei a seca sobre a terra, sobre os montes, sobre o trigo, sobre o suco de uva, sobre o azeite, e sobre tudo o que a terra produz, e sobre os homens sobre e os animais, e sobre todo trabalho manual.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 12, 'Então Zorobabel filho de Sealtiel, Josué filho de Jeozadaque, sumo sacerdote, e todo o resto do povo, ouviram a voz do SENHOR seu Deus, e as palavras do profeta Ageu, como o SENHOR Deus deles havia o enviado; e o povo temeu diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 13, 'Então Ageu, mensageiro do SENHOR, falou mensagem do SENHOR ao povo, dizendo: Eu estou convosco, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 14, 'E o SENHOR despertou o espírito de Zorobabel, filho de Sealtiel, governador de Judá, e o espírito de Josué filho de Jeozadaque, sumo sacerdote, e o espírito de todo o resto do povo; e vieram e começaram a obra na casa do SENHOR dos exércitos, Deus deles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 1, 15, 'No vigésimo quarto dia do sexto mês, no segundo ano do rei Dario.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 1, 'No sétimo mês, no vigésimo primeiro [dia] mês, veio a palavra do SENHOR por meio do profeta Ageu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 2, 'Fala agora a Zorobabel filho de Sealtiel, governador de Judá, e a Josué filho de Jeozadaque, sumo sacerdote, e ao resto do povo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 3, 'Quem restou dentre vós que tenha visto esta casa em sua primeira glória? E como a vedes agora? Não é esta como nada diante de vossos olhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 4, 'Agora, pois, esforça-te, Zorobabel, diz o SENHOR; esforça-te também Josué, filho de Jeozadaque, sumo sacerdote; e esforça-te, todo o povo da terra, diz o SENHOR, e trabalhai; porque eu estou convosco, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 5, 'Conforme o pacto que estabeleci convosco quando saístes do Egito, assim meu Espírito está em meio de vós; não temais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 6, 'Porque assim diz o SENHOR dos exércitos: Ainda uma vez, daqui a pouco, eu farei tremer os céus e a terra, o mar e a terra seca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 7, 'E farei tremer a todas as nações, e virá as coisas preciosas de todas as nações; e encherei esta casa de glória, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 8, 'Minha é a prata, e meu é o ouro, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 9, 'A glória desta última casa será maior que a da primeira, diz o SENHOR dos exércitos; e neste lugar darei paz, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 10, 'Ao vigésimo quarto [dia] do nono mês, no segundo ano de Dario, veio a palavra do SENHOR por mão do profeta Ageu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 11, 'Assim diz o SENHOR dos exércitos: Pergunta agora aos sacerdotes acerca da lei, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 12, 'Se alguém levar carnes santas na borda de sua veste, e com sua borda tocar o pão, a comida, o vinho, o azeite, ou qualquer [outra] comida, por acaso isso será santificado?E os sacerdotes responderam: Não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 13, 'E Ageu disse: Se um impuro por causa de um corpo morto tocar alguma destas coisas, ela será impura? E os sacerdotes responderam: Impura será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 14, 'Então Ageu respondeu: Assim é este povo, esta nação, diante de mim, diz o SENHOR; e assim é toda obra de suas mãos; e todo o que ali oferecem é impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 15, 'Agora pois, considerai desde este dia em diante, antes que se ponha pedra sobre pedra no templo do SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 16, 'Antes que fossem estas coisas, vinham ao amontoado de grãos [buscar] vinte [medidas] , conseguiam[apenas] dez; vinham à prensa de uvas para tirar dali cinquenta [vasos] mas ali havia[somente] vinte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 17, 'Eu vos feri com ferrugem, mofo, e granizo em toda obra de vossas mãos; mas não vos [convertestes] a mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 18, 'Considerai, pois, isto, desde este dia em diante, desde o dia vigésimo quatro [dia] do nono mês, desde o dia em o fundamento do templo do SENHOR foi posto; considerai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 19, 'Ainda há semente no celeiro? A videira, a figueira, a romeira, e oliveira ainda não têm dado frutos; mas a partir de hoje eu [vos] abençoarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 20, 'E a palavra do SENHOR veio pela segunda vez a Ageu, ao vigésimo quarto [dia] do mês, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 21, 'Fala a Zorobabel, governador de Judá, dizendo: Eu farei tremer os céus e a terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 22, 'E transtornarei o trono dos reinos, e destruirei a força dos reinos das nações; e transtornarei as carruagens, e os que nelas se sentam; e os cavalos e os que neles montam cairão, cada um pela espada de seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 37, 'Ageu', 'Ag', 2, 23, 'Naquele dia, diz o SENHOR dos exércitos, eu te tomarei, Zorobabel, filho de Sealtiel, servo meu, diz o SENHOR, e te porei como anel de selar; porque eu te escolhi, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 1, 'No oitavo mês do segundo ano de Dario, a palavra do SENHOR veio ao profeta Zacarias, filho de Berequias, filho de Ido, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 2, 'O SENHOR se irou muito contra vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 3, 'Portanto dize-lhes: Assim diz o SENHOR dos exércitos: Voltai-vos a mim, diz o SENHOR dos exércitos, e eu me voltarei a vós, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 4, 'E não sejais como vossos pais, aos quais os profetas antigos clamavam, dizendo: Assim diz o SENHOR dos exércitos: Convertei-vos de vossos maus caminhos e de vossos maus atos; porém não escutaram, nem me deram ouvidos, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 5, 'Onde estão vossos pais? E os profetas, vivem eles para sempre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 6, 'Porém quanto às minhas palavras e meus estatutos que havia mandado a meus servos os profetas, não alcançaram a vossos pais? Assim eles, arrependendo-se, diziam: Tal como o SENHOR dos exércitos planejou fazer segundo nossos caminhos e nossos antos, assim ele fez conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 7, 'No vigésimo quarto dia do décimo primeiro mês (que é o mês de Sebate), no ano segundo de Dario, a palavra do SENHOR veio ao profeta Zacarias, filho de Berequias, filho de Ido, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 8, 'Vi de noite, e eis um homem montado sobre um cavalo vermelho, parado entre as murtas que estavam num vale profundo; e atrás dele estavam cavalos vermelhos, castanhos, e brancos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 9, 'E eu disse: Meu senhor, o que são estes? E o anjo que falava comigo me disse: Eu te mostrarei o que estes são.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 10, 'Então o homem que estava entre os murtas respondeu, dizendo: Estes são os que o SENHOR enviou para andarem pela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 11, 'E eles responderam ao anjo do SENHOR que estava entre os murtas, e disseram: Nós já andamos pela terra, e eis que toda a terra está tranquila e quieta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 12, 'Então o anjo do SENHOR disse: Ó SENHOR dos exércitos, até quando não terás compaixão de Jerusalém e das cidades de Judá, contra as quais ficaste irado estes setenta anos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 13, 'E o SENHOR respondeu ao anjo que falava comigo palavras boas, palavras de consolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 14, 'E o anjo que falava comigo me disse: Fala em voz alta, dizendo: Assim diz o SENHOR dos exércitos: Tenho grande zelo por Jerusalém e por Sião;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 15, 'E tenho muito grande ira contra as nações tranquilas; porque eu estava pouco irado, porém elas pioraram o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 16, 'Portanto assim diz o SENHOR: Eu me voltarei a Jerusalém com misericórdia; minha casa será reconstruída nela, diz o SENHOR dos exércitos, e a corda de medir será estendida sobre Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 17, 'Fala em voz alta mais, dizendo: Assim diz o SENHOR dos exércitos: Minhas cidades novamente transbordarão de prosperidade; porque o SENHOR novamente consolará a Sião, e novamente escolherá a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 18, 'Depois levantei meus olhos, e olhei, e eis que havia quatro chifres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 19, 'E perguntei ao anjo que falava comigo: O que são estes? E ele me disse: Estes são os chifres que dissiparam Judá, a Israel, e Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 20, 'E o SENHOR me mostrou quatro ferreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 1, 21, 'Então eu disse: O que estes vêm a fazer? E ele falou, dizendo: Estes são os chifres que dispersaram Judá, de modo que ninguém levantava sua cabeça. Estes [ferreiros] vieram para derrubar os chifres das nações, que levantaram [seus] chifres contra a terra de Judá para dispersá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 1, 'Voltei a levantar meus olhos, e olhei, e eis um homem que tinha em sua mão uma corda de medir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 2, 'E eu perguntei: Para onde vais? E ele me respondeu: Vou medir a Jerusalém, para ver quanta é sua largura e quanto é o seu comprimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 3, 'E eis que o anjo que falava comigo saiu, e outro anjo veio ao seu encontro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 4, 'E disse-lhe: Corre, fala a este rapaz, dizendo: Jerusalém será habitada sem muros por causa da multidão de pessoas e de animais que estarão no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 5, 'E eu, diz o SENHOR, serei seu muro de fogo ao redor, e serei [sua] glória no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 6, 'Ei! Ei! Fugi agora da terra do norte, diz o SENHOR, Porque eu vos espalhei pelos quatro ventos dos céu, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 7, 'Ei Sião! Escapa-te tu, que habitas com a filha da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 8, 'Porque assim diz o SENHOR dos exércitos: Foi por causa da glória que ele me enviou às nações que vos despojaram; porque quem vos toca, toca a menina de seu olho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 9, 'Pois eis que levantarei minha mão contra eles, e serão saqueados por seus [próprios] servos, e sabereis que o SENHOR dos exércitos me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 10, 'Canta e alegra-te, ó filha de Sião; porque eis que venho, e habitarei no meio de ti, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 11, 'E naquele dia muitas nações se ajuntarão ao SENHOR, e serão meu povo, e habitarei no meio de ti; e saberás que o SENHOR dos exércitos me enviou a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 12, 'E o SENHOR herdará a Judá como sua propriedade na terra santa, e novamente escolherá a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 2, 13, 'Calem-se todos diante do SENHOR, porque ele se levantou de sua santa morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 1, 'Depois ele me mostrou o sumo sacerdote Josué, que estava diante do anjo do SENHOR; e Satanás estava à sua direita para o acusar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 2, 'Mas o SENHOR disse a Satanás: O SENHOR te repreenda, Satanás; o SENHOR, que escolheu a Jerusalém, te repreenda. Não é este [homem] um tição tirado do fogo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 3, 'E Josué estava vestido com roupas impuras enquanto estava diante do anjo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 4, 'Então [o anjo] falou aos que estavam diante de dele, dizendo: Tirai dele essas roupas impuras. E a ele disse: Eis que tirei de ti tua perversidade, e te vestirei de roupas refinadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 5, 'Depois disse: Ponham um turbante limpo sobre sua cabeça. E puseram um turbante limpo sobre sua cabeça, e puseram-lhe roupas, enquanto o anjo do SENHOR estava [junto] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 6, 'E o anjo do SENHOR exortou a Josué, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 7, 'Assim diz o SENHOR dos exércitos: Se andares em meus caminhos, e guardares minha ordenança, também tu julgarás minha casa e guardarás meus pátios; e te darei passagem entre os que [aqui] estão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 8, 'Ouvi, pois, Josué sumo sacerdote, tu, e teus colegas que se sentam diante de ti; porque são um sinal; pois eis que eu trarei a meu servo, o Renovo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 9, 'Porque eis que, quanto à pedra que pus diante de Josué, sobre esta pedra há sete olhos; eis que gravarei nela uma inscrição, diz o SENHOR dos exércitos, e tirarei a injustiça desta terra em um dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 3, 10, 'Naquele dia, diz o SENHOR dos exércitos, cada um de vós convidará a seu próximo para debaixo da videira, e para debaixo da figueira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 1, 'E o anjo que falava comigo voltou e me despertou, tal como se desperta um homem de seu sono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 2, 'E ele me disse: O que vês? E eu respondi: Eis que vejo um castiçal de ouro maciço, com um recipiente de azeite sobre seu topo, e sete lâmpadas sobre ele; e cada uma das sete lâmpadas tinha um tubo em seu topo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 3, 'E duas oliveiras junto a ele, uma à direita do recipiente, e uma à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 4, 'E eu perguntei ao anjo que falava comigo, dizendo: Meu senhor, o que é isto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 5, 'E o anjo que falava comigo respondeu dizendo: Tu não sabes que é isto? E eu disse: Não, meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 6, 'E ele falou comigo, dizendo: Esta é palavra do SENHOR a Zorobabel, que diz: Não [se fará] por força, nem por violência, mas sim por meu espírito, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 7, 'Quem és tu, montanha grande? Diante de Zorobabel se tornarás em planície; ele trará a pedra angular com gritos de: Graça! graça seja!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 8, 'E palavra do SENHOR veio a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 9, 'As mãos de Zorobabel fundaram esta casa; também suas mãos a completarão, para que saibais que o SENHOR dos exércitos me enviou até vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 10, 'Pois quem despreza o dia das pequenas coisas? Pois esses sete se alegrarão ao verem o prumo na mão de Zorobabel (esses são os olhos do SENHOR, que percorrem toda a terra).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 11, 'E eu respondi, perguntando: O que são as duas oliveiras à direita e à esquerda do castiçal?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 12, 'E também lhe perguntei: O que são aqueles dois ramos de oliveiras que estão de lado dos dois tubos de ouro que derramam [azeite] dourado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 13, 'E ele falou comigo, dizendo: Tu não sabes o que é isto? E eu disse: Não, meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 4, 14, 'Então ele disse: Estes são os dois ungidos que estão diante do Senhor de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 1, 'E outra vez levantei meus olhos, e olhei, e eis um rolo que voava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 2, 'E ele me perguntou: O que vês? E eu disse: Vejo um rolo que voa, cujo comprimento é de vinte, e sua largura de dez côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 3, 'Então me disse: Esta é a maldição que sairá por toda a face da terra, porque qualquer um que furtar (conforme está de um lado do [rolo] ) será removido; e todo aquele que jura [falsamente] , (conforme está do outro lado do [rolo] ) será removido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 4, 'Eu a mando,diz o SENHOR dos exércitos, para que venha à casa do ladrão, e à casa do que jura falsamente pelo meu nome; e fique no meio de sua casa, e a destrua com suas colunas e suas pedras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 5, 'E o anjo que falava comigo veio e me disse: Levanta agora teus olhos, e vê o que é que está chegando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 6, 'E eu perguntei: O que é isto? E ele disse: Isto é um cesto de medir que está saindo.E disse mais: Este é o olho deles em toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 7, 'E eis que uma tampa de chumbo foi levantada, e uma mulher estava sentada no meio do cesto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 8, 'E ele disse: Esta é a Perversidade. E a lançou dentro do cesto, e lançou o peso de chumbo em sua abertura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 9, 'E levantei meus olhos, e vi, e eis que duas mulheres saíram, e havia vento sob suas asas (pois tinham asas como de cegonha), e levantaram o cesto entre a terra e o céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 10, 'Então eu disse ao anjo que falava comigo: Para onde elas estão levando o cesto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 5, 11, 'E ele me respondeu: Para lhe edificarem uma casa na terra de Sinar e, quando estiver pronta, e seja posto em sua base.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 1, 'E outra vez levantei meus olhos, e vi, e eis que quatro carruagens saíram dentre dois montes, e estes montes eram montes de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 2, 'Na primeira carruagem havia cavalos vermelhos, e na segunda carruagem cavalos pretos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 3, 'E na terceira carruagem cavalos brancos, e na quarto carruagem cavalos malhados. E [os cavalos] eram fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 4, 'E perguntei ao anjo que falava comigo: O que é isto, meu senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 5, 'E o anjo me respondeu: Estes são os quatro espíritos dos céus, que saem de onde estavam diante do Senhor de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 6, 'A [carruagem] em que estão os cavalos pretos vai para a terra do norte; os brancos vão atrás deles, e os malhados vão para a terra do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 7, 'E os fortes [cavalos] saíram, e procuraram ir a andarem pela terra. E ele disse: Ide, andai pela terra. E eles andaram pela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 8, 'E ele me chamou, e falou comigo, dizendo: Eis que aqueles que foram para a terra do norte fizeram descansar meu Espírito na terra do norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 9, 'E a palavra do SENHOR veio a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 10, 'Toma dos que foram levados cativos: Heldai, e de Tobias, e de Jedaías, que voltaram da Babilônia; e naquele mesmo dia vem, e entra na casa de Josias, filho de Sofonias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 11, 'Toma prata e ouro, e faze coroas, e põe sobre a cabeça do sumo sacerdote Josué, filho de Jeozadaque;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 12, 'E fala com ele, dizendo: Assim diz o SENHOR dos exércitos: Eis aqui o homem cujo nome é Renovo; ele brotará de seu lugar, e edificará o templo do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 13, 'Ele mesmo edificará o templo do SENHOR, e levará sobre si majestade; e se sentará e dominará em seu trono, e será sacerdote em seu trono; e haverá conselho de paz entre ambos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 14, 'E as coroas serão para Helem, Tobias, e Jedaías, e Hem, filho de Sofonias, como memorial no templo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 6, 15, 'E os que estão longe virão e participarão da construção do templo do SENHOR, e vós sabereis que o SENHOR dos exércitos me enviou a vós. Isto acontecerá se verdadeiramente ouvirdes à voz do SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 1, 'Aconteceu, pois, no quarto ano do rei Dario, que a palavra do SENHOR veio a Zacarias noquarto [dia] do nono mês, [que é] Quisleu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 2, 'Quando os de Betel enviaram Sarezer e Regém-Meleque e seus homens, para suplicarem o favor do SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 3, 'E para dizerem aos sacerdotes que estavam na casa do SENHOR dos exércitos e aos profetas o seguinte: Devemos chorar e jejuar no quinto mês, como já temos feito há tantos anos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 4, 'Então a palavra do SENHOR dos exércitos veio a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 5, 'Fala a todo o povo desta terra, e aos sacerdotes, dizendo: Quando jejuastes e chorastes no quinto e no sétimo [mês] durante estes setenta anos, por acaso jejuastes verdadeiramente para mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 6, 'E quando comeis e bebeis, não foi para vós que comeis e bebeis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 7, 'Não são estas as palavras que o SENHOR pregou por meio dos antigos profetas, quando Jerusalém estava habitada e tranquila, com suas cidades ao seu redor, e o Sul e a campina eram habitadas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 8, 'E a palavra do SENHOR veio a Zacarias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 9, 'Assim falou o SENHOR dos exércitos, dizendo: Julgai juízo verdadeiro, e praticai piedade e misericórdia cada um com seu irmão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 10, 'Não oprimais à viúva, nem ao órfão, nem ao estrangeiro, nem ao pobre; e ninguém planeje o mal em seu coração contra seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 11, 'Porém não quiseram prestar atenção; ao invés disso deram as costas e taparam suas orelhas para não ouvirem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 12, 'E fizeram seus corações duros como diamante, para não ouvirem a Lei nem as palavras que o SENHOR dos exércitos enviou por seu Espírito através dos antigos profetas; por isso veio grande ira da parte do SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 13, 'Por causa disso, tal como eles não ouviram quando eu clamei, assim tamb em quando eles clamaram eu não ouvi,diz o SENHOR dos exércitos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 7, 14, 'E eu os espalhei com turbilhão entre todas as nações, que eles não conheciam, e a terra foi assolada atrás deles, de maneira que ninguém passava por ela, nem voltava; porque tornaram a terra desejada em ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 1, 'Depois veio a palavra do SENHOR dos exércitos, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 2, 'Assim diz o SENHOR dos exércitos: Tenho grande zelo por Sião, e com grande furor zelo por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 3, 'Assim diz o SENHOR: Eu voltarei a Sião, e habitarei no meio de Jerusalém. E Jerusalém será chamada Cidade da Verdade, e o monte do SENHOR dos exércitos, Monte Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 4, 'Assim diz o SENHOR dos exércitos: Novamente idosos e idosas se sentarão nas praças de Jerusalém, e cada um terá seu bordão em sua mão, por causa da abundância de dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 5, 'E as ruas da cidade se encherão de meninos e meninas, brincando em suas ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 6, 'Assim diz o SENHOR dos exércitos: Se isto era extraordinário demais aos olhos do restante do povo naqueles dias, seria também extraordinário demais aos meus olhos? Diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 7, 'Assim disse o SENHOR dos exércitos: Eis que salvarei o meu povo da terra do oriente, e da terra do ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 8, 'Eu os trarei, e habitarão no meio de Jerusalém; e eles serão meu povo, e eu serei o Deus deles em verdade e em justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 9, 'Assim diz o SENHOR dos exércitos: Sejam fortes vossas mãos, vós que nestes dias ouvistes estas palavras da boca dos profetas que estiveram no dia em que foi posto o fundamento da casa do SENHOR dos exércitos, para que o templo fosse edificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 10, 'Porque antes daqueles dias não houve salário para homem, nem salário para animal, e o que entrava e o que saía não tinha paz por causa do inimigo, porque eu mandei a todos, cada um contra seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 11, 'Mas agora com o resto deste povo não farei como nos dias passados, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 12, 'Porque a semente será próspera, a vide dará seu fruto, a terra dará seu produto, e os céus darão seu orvalho; e farei o resto deste povo herdar tudo isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 13, 'E será, ó casa de Judá e casa de Israel, que, assim como fostes maldição entre as nações, assim também eu vos salvarei, e sereis bênção. Não temais, fortaleçam-se vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 14, 'Porque assim diz o SENHOR dos exércitos: Assim como eu pensei vos fazer o mal quando vossos pais me provocaram à ira, diz o SENHOR dos exércitos, e não me arrependi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 15, 'Assim também voltei a pensar em fazer o bem a Jerusalém e à casa de Judá nestes dias; não temais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 16, 'Estas são as coisas que deveis fazer: falai verdade cada qual com seu próximo; julgai em vossas portas verdade e juízo de paz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 17, 'E ninguém planeje o mal em seu coração contra seu próximo, nem ameis o juramento falso; porque eu odeio todas estas coisas, diz o SENHOR'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 18, 'E a palavra do SENHOR dos exércitos veio a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 19, 'Assim diz o SENHOR dos exércitos: O jejum do quarto, do quinto, do sétimo, e do décimo mês, se voltarão à casa de Judá serão para prazer e alegria, e para festividades solenes. Amai, pois, a verdade e a paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 20, 'Assim diz o SENHOR dos exércitos: Ainda será que povos e moradores de muitas cidades virão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 21, 'E irão os moradores de uma [cidade] à outra, dizendo: Vamos suplicar o favor do SENHOR, e buscar ao SENHOR dos exércitos. Eu também irei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 22, 'Assim muitos povos e poderosas nações virão para buscar ao SENHOR dos exércitos em Jerusalém, e suplicar o favor do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 38, 'Zacarias', 'Zc', 8, 23, 'Assim diz o SENHOR dos exércitos: Naqueles dias será que dez homens de todas as línguas das nações, pegarão na orla da veste de um judeu, dizendo: Iremos convosco, porque temos ouvido que Deus está convosco.')
